package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

var (
	users  = make(map[string]User)
	mutex  sync.RWMutex
	nextID = 1 // This will be removed once uuid is fully integrated
)

// GetAllUsers returns a list of all users
func GetAllUsers() []User {
	mutex.RLock()
	defer mutex.RUnlock()
	var list []User
	for _, u := range users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user
func CreateUser(u User) User {
	mutex.Lock()
	defer mutex.Unlock()
	u.ID = uuid.New().String() // Using uuid for ID generation
	users[u.ID] = u
	return u
}

// GetUserByID retrieves a user by ID
func GetUserByID(id string) (User, bool) {
	mutex.RLock()
	defer mutex.RUnlock()
	u, ok := users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"

	"rep-4/internal/service"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// HandleUsers handles requests to /users
func HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		list := service.GetAllUsers()
		json.NewEncoder(w).Encode(list)

	case http.MethodPost:
		var u User
		if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		serviceUser := service.User{Name: u.Name, Email: u.Email}
		createdUser := service.CreateUser(serviceUser)
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(createdUser)

	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// HandleUserByID handles requests to /users/{id}
func HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	switch r.Method {
	case http.MethodGet:
		u, ok := service.GetUserByID(id)
		if !ok {
			http.NotFound(w, r)
			return
		}
		json.NewEncoder(w).Encode(u)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

package main

import (
	"log"
	"net/http"

	"rep-4/internal/api"
)

func main() {
	http.HandleFunc("/users", api.HandleUsers)
	http.HandleFunc("/users/", api.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service_test

import (
	"testing"

	"github.com/stretchr/testify/assert"

	"rep-4/internal/service"
)

func TestCreateAndGetUsers(t *testing.T) {
	// Clear existing users for a clean test environment (if necessary)
	// In a real application, you might use a mock or separate test database
	// For this example, we'll assume a fresh start or add a reset function to the service

	user1 := service.User{Name: "Alice", Email: "alice@example.com"}
	createdUser1 := service.CreateUser(user1)

	assert.NotEmpty(t, createdUser1.ID)
	assert.Equal(t, "Alice", createdUser1.Name)
	assert.Equal(t, "alice@example.com", createdUser1.Email)

	retrievedUser1, ok := service.GetUserByID(createdUser1.ID)
	assert.True(t, ok)
	assert.Equal(t, createdUser1, retrievedUser1)

	user2 := service.User{Name: "Bob", Email: "bob@example.com"}
	createdUser2 := service.CreateUser(user2)

	assert.NotEmpty(t, createdUser2.ID)

	allUsers := service.GetAllUsers()
	assert.Len(t, allUsers, 2)
	assert.Contains(t, allUsers, createdUser1)
	assert.Contains(t, allUsers, createdUser2)
}

func TestGetUserNotFound(t *testing.T) {
	_, ok := service.GetUserByID("nonexistent-id")
	assert.False(t, ok)
}
